#!/usr/bin/env python3
"""Package FFmpegKit's xcframeworks as SwiftPM binary-target zips (runs on the macOS CI runner).

For every binary target the FFmpegKit target needs:
  - copy fk/Sources/<name>.xcframework
  - keep only the visionOS and tvOS *device* libraries (the app builds nothing else), so no
    unpatched simulator / iOS / macOS slices are distributed
  - for Libavformat, drop in the patched binaries from out/
  - zip with ditto and compute the SwiftPM checksum
Then write Vendor/FFmpegKit/Package.swift pointing at the release download URLs.

usage: package_xcframeworks.py <fk dir> <patched dir> <out dir> <release base url> <package.swift path>
"""
import json
import plistlib
import shutil
import subprocess
import sys
from pathlib import Path

# Binary dependencies of the FFmpegKit target in FFmpegKit 6.1.4's Package.swift, minus
# libbluray (macOS-only there). Order kept for a readable Package.swift.
TARGETS = [
    "MoltenVK", "libshaderc_combined", "lcms2", "libdav1d", "libplacebo", "libzvbi", "libsrt",
    "libfreetype", "libfribidi", "libharfbuzz", "libass", "libfontconfig",
    "gmp", "nettle", "hogweed", "gnutls", "libsmbclient",
    "Libavcodec", "Libavdevice", "Libavfilter", "Libavformat", "Libavutil", "Libswresample", "Libswscale",
]
KEEP_PLATFORMS = {"xros", "tvos"}


def strip_xcframework(path: Path) -> list[str]:
    info_path = path / "Info.plist"
    info = plistlib.loads(info_path.read_bytes())
    kept, dropped = [], []
    for lib in info["AvailableLibraries"]:
        device = lib["SupportedPlatform"] in KEEP_PLATFORMS and "SupportedPlatformVariant" not in lib
        (kept if device else dropped).append(lib)
    if not kept:
        raise SystemExit(f"{path.name}: no visionOS/tvOS device slice")
    for lib in dropped:
        shutil.rmtree(path / lib["LibraryIdentifier"], ignore_errors=True)
    info["AvailableLibraries"] = kept
    info_path.write_bytes(plistlib.dumps(info, fmt=plistlib.FMT_XML))
    return [lib["LibraryIdentifier"] for lib in kept]


def main() -> None:
    fk, patched, out, base_url, package_swift = (Path(a) for a in sys.argv[1:6])
    base_url = str(sys.argv[4]).rstrip("/")
    stage = out / "stage"
    shutil.rmtree(stage, ignore_errors=True)
    stage.mkdir(parents=True)
    checksums = {}
    for name in TARGETS:
        src = fk / "Sources" / f"{name}.xcframework"
        dst = stage / src.name
        shutil.copytree(src, dst, symlinks=True)
        slices = strip_xcframework(dst)
        if name == "Libavformat":
            for ident in slices:
                binary = dst / ident / "Libavformat.framework" / "Libavformat"
                replacement = patched / f"Libavformat-{ident}"
                if not replacement.exists():
                    raise SystemExit(f"missing patched binary for {ident}")
                shutil.copyfile(replacement, binary)
        zip_path = out / f"{name}.xcframework.zip"
        zip_path.unlink(missing_ok=True)
        subprocess.run(["ditto", "-c", "-k", "--sequesterRsrc", "--keepParent", str(dst), str(zip_path)], check=True)
        checksum = subprocess.run(["swift", "package", "compute-checksum", str(zip_path)],
                                  check=True, capture_output=True, text=True).stdout.strip()
        checksums[name] = checksum
        print(f"{name:22s} {','.join(slices):32s} {zip_path.stat().st_size / 1e6:7.1f} MB  {checksum}")

    (out / "checksums.json").write_text(json.dumps(checksums, indent=2) + "\n")

    deps = ",\n".join(f'                "{n}"' for n in TARGETS)
    binaries = "\n".join(
        f'        .binaryTarget(\n            name: "{n}",\n'
        f'            url: "{base_url}/{n}.xcframework.zip",\n'
        f'            checksum: "{checksums[n]}"\n        ),'
        for n in TARGETS)
    package_swift.write_text(f'''// swift-tools-version:5.9
// GENERATED by Vendor/FFmpegKit/tools/package_xcframeworks.py (workflow "FFmpegKit backports").
// FFmpegKit 6.1.4 (kingslay/FFmpegKit, GPLv3, see LICENSE) with Libavformat's mov.o + hls.o
// rebuilt from FFmpeg n6.1 + Vendor/FFmpegKit-patches. visionOS + tvOS device slices only.
import PackageDescription

let package = Package(
    name: "FFmpegKit",
    platforms: [.tvOS(.v13), .visionOS(.v1)],
    products: [
        .library(name: "FFmpegKit", targets: ["FFmpegKit"]),
    ],
    targets: [
        .target(
            name: "FFmpegKit",
            dependencies: [
{deps},
            ],
            linkerSettings: [
                .linkedFramework("AudioToolbox"),
                .linkedFramework("AVFAudio"),
                .linkedFramework("AVFoundation"),
                .linkedFramework("CoreAudio"),
                .linkedFramework("CoreVideo"),
                .linkedFramework("CoreFoundation"),
                .linkedFramework("CoreGraphics"),
                .linkedFramework("CoreMedia"),
                .linkedFramework("Foundation"),
                .linkedFramework("Metal"),
                .linkedFramework("IOKit", .when(platforms: [.visionOS])),
                .linkedFramework("IOSurface"),
                .linkedFramework("QuartzCore"),
                .linkedFramework("Security"),
                .linkedFramework("UIKit"),
                .linkedFramework("VideoToolbox"),
                .linkedLibrary("bz2"),
                .linkedLibrary("c++"),
                .linkedLibrary("iconv"),
                .linkedLibrary("resolv"),
                .linkedLibrary("xml2"),
                .linkedLibrary("z"),
            ]
        ),
{binaries}
    ]
)
''')
    print(f"wrote {package_swift}")


if __name__ == "__main__":
    main()
